   group('Invite QR domain use cases', () {
+    const buildUsecase = BuildInviteQr();
+    const parseUsecase = ParseInviteFromQr();
+
+    const testInvite = RoomInvite(
+      host: '192.168.1.10',
+      port: 47800,
+      roomId: 'room-alpha-123',
+      accessCode: '5678',
